for i,p in c.execute("SELECT item_code,population_code FROM item_population_links"):
    direct.setdefault(i,set()).add(p)
axis={}
for i,p in c.execute("""SELECT ial.item_code, pam.population_code
                        FROM item_axis_links ial JOIN population_axis_map pam
                        ON pam.axis_code=ial.axis_code"""):
    axis.setdefault(i,set()).add(p)
items={r[0] for r in c.execute("SELECT item_code FROM items")}
agree=dis=onlyd=onlya=neither=0
for i in items:
    d,a=direct.get(i),axis.get(i)
    if d and a: (agree:=agree+1) if d==a else (dis:=dis+1)
    elif d: onlyd+=1
    elif a: onlya+=1
    else: neither+=1
print(f"  items: {len(items)}   both routes agree: {agree}   DISAGREE: {dis}")
print(f"  only direct: {onlyd}   only axis-route: {onlya}   neither: {neither}")

